// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint256 putAmount, uint256 collectAmount, address actor) public {
        vm.assume(putAmount <= VALUE_CAP);
        // Keep the actor from being the test contract or the zero address so we control the call path.
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // Admissible domain: put enough to meet MinSum, and collect a positive amount.
        uint256 minSum = c.MinSum();
        putAmount = bound(putAmount, minSum, type(uint128).max);
        collectAmount = bound(collectAmount, 1, putAmount);

        vm.deal(actor, putAmount);

        // Put at a future unlock time so the only way to differentiate P and M is the strict vs. non-strict comparison.
        uint256 unlockTime = block.timestamp + 1 days;

        vm.prank(actor);
        c.Put{value: putAmount}(unlockTime);

        // Warp exactly to the unlock time: P's `>` fails, M's `>=` succeeds.
        vm.warp(unlockTime);

        (uint256 unlockBefore, uint256 balanceBefore) = c.Acc(actor);
        assertTrue(balanceBefore == putAmount, "setup: put did not record balance");

        vm.prank(actor);
        c.Collect(collectAmount);

        (uint256 unlockAfter, uint256 balanceAfter) = c.Acc(actor);

        // General rule: at the boundary (now == unlockTime), no successful withdrawal may occur.
        // The reference leaves the balance untouched; the buggy >= mutant decreases it.
        assertTrue(balanceAfter == balanceBefore, "Collect must not withdraw when block.timestamp equals unlockTime");
    }
}
